@extends('layouts.app') @section('content')<div class="page-head"><div><h1>Inventory</h1><p>Stock, valuation and traceable movements.</p></div><a class="primary" href="{{ route('inventory.create') }}">+ New Product</a></div><div class="panel"><table><thead><tr><th>SKU</th><th>Product</th><th>Brand</th><th>Stock</th><th>Min</th><th>Sell Price</th><th>Action</th></tr></thead><tbody>@foreach($items as $i)<tr><td>{{ $i->product->sku }}</td><td><b>{{ $i->product->name }}</b></td><td>{{ $i->product->brand }}</td><td><span class="{{ $i->quantity <= $i->product->minimum_stock ? 'danger-text':'' }}">{{ $i->quantity }}</span></td><td>{{ $i->product->minimum_stock }}</td><td>Rs. {{ number_format($i->product->selling_price,2) }}</td><td><form class="inline-form" method="post" action="{{ route('inventory.adjust',$i->product) }}">@csrf<input name="quantity" type="number" step=".001" placeholder="+/- qty"><input name="reason" placeholder="Reason"><button>Adjust</button></form></td></tr>@endforeach</tbody></table>{{ $items->links() }}</div>@endsection
